kelvin_to_celsius <- function(temp) {
  celsius <- temp - 273.15
  return(celsius)
}
kelvin_to_celsius(273.15)

cv <- function(x) {
  round(sd(x) / mean(x) * 100, 1)
}
print(cv(mtcars$mpg))
print(cv(mtcars$hp))

fahr_to_kelvin <- function(temp) {
  (temp - 32) * (5 / 9) + 273.15
}
kelvin_to_celsius <- function(temp) {
  temp - 273.15
}
fahr_to_celsius <- function(temp) {
  stopifnot(is.numeric(temp))
  temp_k <- fahr_to_kelvin(temp)
  kelvin_to_celsius(temp_k)
}
fahr_to_celsius(32)

threshold <- 50
for (cont in unique(gapminder$continent)) {
  m <- mean(gapminder[gapminder$continent == cont, "lifeExp"])
  if (m < threshold) {
    cat("Average life expectancy in", cont, "is less than", threshold, "\n")
  } else {
    cat("Average life expectancy in", cont, "is greater than", threshold, "\n")
  }
}

best_practice <- c("Write", "programs", "for", "people", "not", "computers")
fence <- function(text, wrapper) {
  text <- c(wrapper, text, wrapper)
  paste(text, collapse = " ")
}
fence(best_practice, "***")

lower <- 50
upper <- 70
for (ctry in unique(gapminder$country)) {
  m <- mean(gapminder[gapminder$country == ctry, "lifeExp"])
  if (m < lower) {
    cat("Average life expectancy in", ctry, "is less than", lower, "\n")
  } else if (m < upper) {
    cat("Average life expectancy in", ctry, "is between", lower, "and", upper, "\n")
  } else {
    cat("Average life expectancy in", ctry, "is greater than", upper, "\n")
  }
}
